// Hardcoded company list for Greenhouse API
const companies = [
  'anthropic',
  'openai',
  'databricks',
  'huggingface',
  'cohere',
  'scale',
  'adept',
  'perplexity',
  'mistral',
  'together',
  'replicate',
  'runwayml',
  'character-ai',
  'elevenlabs',
  'midjourney'
];

return companies.map(slug => ({
  json: { company_slug: slug }
}));

// Aggregate, filter by keywords, dedupe, take top 20 by recency
const allJobs = [];
const seen = new Set();

// Role keywords to filter (broad ML/AI/Software match)
const keywords = [
  'engineer', 'developer', 'scientist', 'researcher',
  'machine learning', 'ml ', 'ai ', 'data', 'backend',
  'software', 'infrastructure', 'platform', 'systems',
  'fullstack', 'full-stack', 'full stack', 'applied',
  'nlp', 'retrieval', 'search', 'python', 'deep learning'
];

for (const item of $input.all()) {
  const jobs = item.json.jobs || [];
  const companySlug = item.json.company_slug || 'unknown';

  for (const job of jobs) {
    if (!job || !job.id) continue;

    const dedupKey = `${job.id}`;
    if (seen.has(dedupKey)) continue;
    seen.add(dedupKey);

    const title = (job.title || '').toLowerCase();
    const dept = ((job.departments || [])[0]?.name || '').toLowerCase();
    const combined = `${title} ${dept}`;

    // Check if job matches any keyword
    const matches = keywords.some(kw => combined.includes(kw));
    if (!matches) continue;

    const location = (job.location?.name || 'Unknown');

    allJobs.push({
      job_id: `${companySlug}-${job.id}`,
      title: job.title,
      company: companySlug,
      location: location,
      department: (job.departments || [])[0]?.name || '',
      url: job.absolute_url || `https://boards.greenhouse.io/${companySlug}/jobs/${job.id}`,
      updated_at: job.updated_at || '1970-01-01',
      description_snippet: (job.content || '').replace(/<[^>]*>/g, '').substring(0, 300)
    });
  }
}

// Sort by updated_at desc (most recent first), take top 20
allJobs.sort((a, b) => new Date(b.updated_at) - new Date(a.updated_at));
const top20 = allJobs.slice(0, 20);

return [{ json: { jobs: top20, count: top20.length } }];

// Build the scorer input: resume summary + jobs batch
const jobs = $('Aggregate Jobs').first().json.jobs;
const resumeBinary = $('Read Resume').first().binary;

// Extract resume text from binary data
let resumeText = '';
if (resumeBinary && resumeBinary.data) {
  resumeText = Buffer.from(resumeBinary.data.data, 'base64').toString('utf-8');
} else {
  resumeText = $('Read Resume').first().json.data || 'No resume found';
}

// Build a condensed summary for the scorer (first 2000 chars)
const masterResumeSummary = resumeText.substring(0, 2000);

const jobBatch = jobs.map(j => ({
  job_id: j.job_id,
  title: j.title,
  company: j.company,
  location: j.location,
  department: j.department,
  url: j.url,
  description_snippet: j.description_snippet
}));

return [{
  json: {
    master_resume_summary: masterResumeSummary,
    jobs: jobBatch
  }
}];

// Format top 5 scored jobs as Telegram message + store in static data
const scorerOutput = $input.first().json.output || $input.first().json;
const scored = scorerOutput.scored || [];
const allJobs = $('Aggregate Jobs').first().json.jobs;

// Take top 5
const top5 = scored.slice(0, 5);

// Build lookup map
const jobMap = {};
for (const j of allJobs) {
  jobMap[j.job_id] = j;
}

// Store in workflow static data for /apply N reference
const staticData = $getWorkflowStaticData('global');
staticData.last_jobs = {};

// Format Telegram message
let msg = '🔍 *Top Job Matches*\n\n';

top5.forEach((s, i) => {
  const num = i + 1;
  const job = jobMap[s.job_id] || {};
  const title = job.title || 'Unknown';
  const company = (job.company || 'unknown').replace(/-/g, ' ');
  const location = job.location || 'Unknown';
  const score = s.fit_score;
  const liner = s.one_liner;
  const url = job.url || '';

  // Store for later /apply N
  staticData.last_jobs[num] = {
    job_id: s.job_id,
    title: title,
    company: company,
    location: location,
    url: url,
    fit_score: score,
    description_snippet: job.description_snippet || ''
  };

  msg += `*${num}.* [${title}](${url})\n`;
  msg += `    🏢 ${company} · 📍 ${location}\n`;
  msg += `    📊 Fit: ${score}/10 — ${liner}\n\n`;
});

msg += '_Reply with a number (1-5) to generate a tailored resume._';

return [{ json: { message: msg } }];

const staticData = $getWorkflowStaticData('global');
const chatId = $('Extract Input').item.json.chat_id;
const entities = $('Route Intent').item.json.output?.entities || $('Route Intent').item.json.output || {};
const jobNumber = entities.job_number;
if (!jobNumber) {
